package httpapi

import("errors";"net/http";"github.com/gin-gonic/gin";"github.com/sagarbagwe/jobapply-ai/backend/internal/ai";"github.com/sagarbagwe/jobapply-ai/backend/internal/model")
func Router(provider ai.Provider)*gin.Engine{r:=gin.New();r.Use(gin.Logger(),gin.Recovery(),securityHeaders());r.GET("/healthz",func(c *gin.Context){c.JSON(http.StatusOK,gin.H{"status":"ok"})});v1:=r.Group("/v1");v1.POST("/match",func(c *gin.Context){var in model.MatchRequest;if err:=c.ShouldBindJSON(&in);err!=nil||in.Job.Description==""{c.JSON(http.StatusBadRequest,gin.H{"error":"invalid request"});return};out,err:=provider.Match(c,in);respond(c,out,err)});v1.POST("/answers",func(c *gin.Context){var in model.AnswerRequest;if err:=c.ShouldBindJSON(&in);err!=nil||in.Question==""{c.JSON(http.StatusBadRequest,gin.H{"error":"invalid request"});return};out,err:=provider.Answer(c,in);respond(c,out,err)});return r}
func respond(c *gin.Context,out any,err error){if err==nil{c.JSON(http.StatusOK,out);return};if errors.Is(err,ai.ErrNotConfigured){c.JSON(http.StatusServiceUnavailable,gin.H{"error":"AI provider not configured"});return};c.JSON(http.StatusBadGateway,gin.H{"error":"AI provider request failed"})}
func securityHeaders()gin.HandlerFunc{return func(c *gin.Context){c.Header("X-Content-Type-Options","nosniff");c.Header("X-Frame-Options","DENY");c.Header("Referrer-Policy","no-referrer");c.Next()}}
